// Pick a depth from 1 to 3 for each half, tag the halves with it,
// then start the quicksand event with both depths packed together.
local upd = CMND_BTL_GET_RAND(1, 4);
local dwd = CMND_BTL_GET_RAND(1, 4);
CMND_BTL_ADD_FLOOR_ATTR("FL01", upd);
CMND_BTL_ADD_FLOOR_ATTR("FL02", dwd);
CMND_BTL_TRIGGER_FLOOR_EV(FLOOR_EVT_QUICKSAND, (dwd << 4) + upd);

// Register one zone when the map loads and give it attribute 0
ScMapInit <- function ()
{
	CMND_BTL_REGIST_FLOOR_ATTR("FL01", -137, -238, 274, 576);
	CMND_BTL_ADD_FLOOR_ATTR("FL01", 0);
};
